#!/usr/bin/bash

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

#shellcheck source=/dev/null
source "$SCRIPT_DIR"/lib/ui.sh
#shellcheck source=/dev/null
source "$SCRIPT_DIR"/lib/ansi.sh
#shellcheck source=/dev/null
source "$SCRIPT_DIR"/lib/itop.sh
cleanup ()
{
    stty echo
    # switch out of alternate screen buffer.
    printf '%s' "$ALT_SCR_OFF"
    printf '%s' "$SHOW_CURSOR"
    exit
}

trap 'cleanup' INT EXIT TERM

RESIZED=1
trap 'RESIZED=1' WINCH

prev_total=0
prev_idle=0

#=====================================================
# !!! CODE GENERATED BY GEMINI. !!!
os_name=$(grep '^PRETTY_NAME=' /etc/os-release | cut -d '"' -f 2)
#=====================================================

kernel_ver=$(uname -r)

# prev_

while IFS=':' read -r key value; do
    if [[ "$key" == "model name"* ]]; then
        model_name=${value# }
        break
    fi
done < /proc/cpuinfo

# switch to alternate buffer.
printf '%s' "$ALT_SCR_ON"

# clear screen and move cursor to (1,1)
printf '%s%s' "$CLR_SCR" "$RST_CURSOR"

# hide cursor
printf '%s' "$HIDE_CURSOR"

#stop displaying user input
stty -echo

# printf '\x1b[48;5;16m'

itop_init

SLEEP_TIME=0.6
# read -r HEIGHT WIDTH < <(stty size)
# main loop
while : ; do 
#   main frame that is flushed to display at the end of every cycle.
    FRAME=$RST_CURSOR
    if [[ $RESIZED == 1 ]] ; then
            read -r HEIGHT WIDTH < <(stty size)
            FRAME=${RST_CUROSR}${CLR_SCR}
            RESIZED=0
    fi
#    printf '\e[2J\e[3J\e[H'

    ui_draw_box 1 1 "$WIDTH" "$HEIGHT" 1 $C_RED
#    ui_draw_box 2 2 "$((WIDTH/2))" "$((HEIGHT/2))" 2 $C_TEAL
    #ui_draw_text "█GREEN█" 3 3 $C_GREEN
    #ui_draw_text "█YELLOW█" 3 10 $C_YELLOW
    #ui_draw_text "█ORANGE█" 3 18 $C_ORANGE
    #ui_draw_text "█RED█" 3 26 $C_RED
    #ui_draw_text "█TEAL█" 3 31 $C_TEAL
#    ui_draw_box 8 8 10 10 1

    ui_draw_text "[ISM v0.0001]" 1 "$(((WIDTH/2) - 6))"

    itop_main 2 2 "$(((WIDTH/2)-2))" "$((HEIGHT-2))"

    ui_draw_box 2 "$(( (WIDTH/2)+2 ))" "$(((WIDTH/2)-4))" "$((HEIGHT-2))" 1 "$C_BLUE"
    ui_draw_text "SYSTEM INFO:" 3 "$(( (WIDTH/2)+3 ))" "$C_BLUE"
    ui_draw_text "OS: ${os_name}" 5 "$(( (WIDTH/2)+3 ))" "$C_BLUE"
    ui_draw_text "Kernel: ${kernel_ver}" 7 "$(( (WIDTH/2)+3 ))" "$C_BLUE"
    ui_draw_text "uptime: $(uptime -p)" 9 "$(( (WIDTH/2)+3 ))" "$C_BLUE"
    # if [[ $HEIGHT -lt 32 ]] ; then
    #     ui_draw_box "$((HEIGHT/2))" "$((WIDTH/2))" "$((WIDTH/4))" "$((HEIGHT/4))" 2 "$C_RED"
    #     ui_draw_text "TERMINAL TOO SMALL" "$((HEIGHT/2 + 4))" "$((WIDTH/2))" "$C_RED"
    # fi
    # final frame pushed to display
    printf "%b" "$FRAME"

    read -rsn1 -t "$SLEEP_TIME" key

done

# restore previous screen
printf '\e[?1049l'